import Phaser from 'phaser';
import type { StageData } from './level/Level';
import { loadSettings, volumeOf } from './settings';
import { getSfxLevel, setSamplePlayer } from './sfx';

/**
 * Music and sampled sound effects generated by `npm run audio` (art/audio.mjs).
 * public/assets/audio/manifest.json lists what exists; anything missing is
 * simply silent (music) or synthesized (sfx).
 */
interface Manifest {
  music: Record<string, string>;
  sfx: Record<string, string>;
  voice?: Record<string, string>;
}

const MUSIC_VOLUME = 0.45;
const SFX_VOLUME = 0.5;
let current: { key: string; sound: Phaser.Sound.WebAudioSound | Phaser.Sound.HTML5AudioSound } | null = null;
/** Music level from the mixer (0..1). */
let musicLevel = volumeOf(loadSettings().music);

/** Change the music level; the playing track follows right away. */
export function setMusicLevel(level: number): void {
  musicLevel = level;
  current?.sound.setVolume(MUSIC_VOLUME * musicLevel);
}

export function preloadAudioManifest(scene: Phaser.Scene): void {
  scene.load.json('audio_manifest', 'assets/audio/manifest.json');
}

/** Queue every file in the manifest; calls `done` once they're loaded. */
export function loadAudio(scene: Phaser.Scene, done: () => void): void {
  const m = scene.cache.json.get('audio_manifest') as Manifest | undefined;
  let queued = 0;
  for (const [name, file] of Object.entries(m?.music ?? {})) {
    scene.load.audio(`music_${name}`, `assets/audio/${file}`);
    queued++;
  }
  for (const [name, file] of Object.entries(m?.voice ?? {})) {
    scene.load.audio(`voice_${name}`, `assets/audio/${file}`);
    queued++;
  }
  for (const [name, file] of Object.entries(m?.sfx ?? {})) {
    scene.load.audio(`sfx_${name}`, `assets/audio/${file}`);
    queued++;
  }
  setSamplePlayer((name) => {
    const key = `sfx_${name}`;
    if (!scene.cache.audio.exists(key)) return false;
    const level = getSfxLevel();
    if (level > 0) scene.sound.play(key, { volume: SFX_VOLUME * level });
    return true;
  });
  if (!queued) {
    done();
    return;
  }
  scene.load.once('complete', done);
  scene.load.start();
}

type Track = Phaser.Sound.WebAudioSound | Phaser.Sound.HTML5AudioSound;

/**
 * Fade a track's volume to `to` over `ms`, independent of any scene (they come
 * and go). Runs on a timer, not animation frames, so it still finishes when
 * the page is in the background; `done` is guaranteed to run once.
 */
function fade(sound: Track, from: number, to: number, ms: number, done?: () => void): void {
  const start = performance.now();
  let finished = false;
  const finish = (): void => {
    if (finished) return;
    finished = true;
    clearInterval(timer);
    try {
      sound.setVolume(to);
    } catch {
      // destroyed meanwhile
    }
    done?.();
  };
  const timer = setInterval(() => {
    const k = Math.min(1, (performance.now() - start) / ms);
    try {
      sound.setVolume(from + (to - from) * k);
    } catch {
      finish();
      return;
    }
    if (k >= 1) finish();
  }, 16);
  setTimeout(finish, ms + 60); // backstop if the interval is throttled
}

/** How long tracks take to fade out and in when one replaces another. */
const CROSSFADE_MS = 420;

/** Told about each track as it starts (the save records it for the jukebox). */
let onTrack: ((key: string) => void) | null = null;
export function setMusicListener(fn: (key: string) => void): void {
  onTrack = fn;
}

/** Loop a music track (no-op if it's already playing or wasn't generated); the old one fades out as it fades in. */
export function playMusic(scene: Phaser.Scene, key: string): void {
  if (current?.key === key) return;
  stopMusic(CROSSFADE_MS);
  const audioKey = `music_${key}`;
  if (!scene.cache.audio.exists(audioKey)) return;
  const sound = scene.sound.add(audioKey, { loop: true, volume: 0 }) as Track;
  sound.play();
  fade(sound, 0, MUSIC_VOLUME * musicLevel, CROSSFADE_MS);
  current = { key, sound };
  onTrack?.(key);
}

/** A one-shot jingle (e.g. after a boss): the music fades out quickly, then it plays once. */
export function playJingle(scene: Phaser.Scene, key: string): void {
  stopMusic(200);
  const audioKey = `music_${key}`;
  if (!scene.cache.audio.exists(audioKey)) return;
  const sound = scene.sound.add(audioKey, { loop: false, volume: MUSIC_VOLUME * musicLevel * 1.1 }) as Track;
  sound.play();
  sound.once('complete', () => sound.destroy());
  current = { key, sound };
  onTrack?.(key);
}

/** Key of what's playing now (music or a jingle), if anything. */
export function nowPlaying(): string | null {
  return current?.key ?? null;
}

/** Stop the music, fading it out over `fadeMs` (0 cuts it). */
export function stopMusic(fadeMs = 0): void {
  const old = current;
  current = null;
  if (!old) return;
  if (fadeMs <= 0) {
    old.sound.stop();
    old.sound.destroy();
    return;
  }
  fade(old.sound, old.sound.volume, 0, fadeMs, () => {
    old.sound.stop();
    old.sound.destroy();
  });
}

/** The track for a stage (fortress stages share one). */
export function stageMusic(stage: StageData): string {
  if (stage.theme === 'fortress') return 'fortress';
  return stage.id;
}

/** Speak a dialogue line (if it was generated). Returns its length in ms, or 0. */
export function playVoice(scene: Phaser.Scene, name: string): number {
  const key = `voice_${name}`;
  if (!scene.cache.audio.exists(key)) return 0;
  const level = getSfxLevel();
  const sound = scene.sound.add(key, { volume: 0.9 * Math.max(level, 0.3) });
  sound.play();
  sound.once('complete', () => sound.destroy());
  return (sound.duration || 0) * 1000;
}

/** A looping sound effect sample (engines, crowds); null if it wasn't generated. */
export function loopSfx(scene: Phaser.Scene, name: string, volume = 0.4): Phaser.Sound.BaseSound | null {
  const key = `sfx_${name}`;
  if (!scene.cache.audio.exists(key)) return null;
  const sound = scene.sound.add(key, { loop: true, volume: volume * getSfxLevel() });
  sound.play();
  return sound;
}
